package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"strings"
)

// Registry is what each project may route, generated by hosts/black/routes.nix
// (which also asserts that no two projects claim the same hostname).
type Registry struct {
	Projects map[string]Project `json:"projects"`
}

// Project lists a project's allowed hostnames (exact, or "*.<domain>" for any
// single label under <domain>), Convex deployments and external upstream
// hosts.
type Project struct {
	Hosts     []string `json:"hosts"`
	Convex    []string `json:"convex"`
	Upstreams []string `json:"upstreams"`
}

var projectName = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$`)

// hostName is a lowercase DNS name with at least two labels.
var hostName = regexp.MustCompile(`^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$`)

func loadRegistry(file string) (*Registry, error) {
	data, err := os.ReadFile(file)
	if err != nil {
		return nil, err
	}
	var r Registry
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&r); err != nil {
		return nil, fmt.Errorf("%s: %w", file, err)
	}
	if err := r.check(); err != nil {
		return nil, fmt.Errorf("%s: %w", file, err)
	}
	return &r, nil
}

// check repeats the registry's invariants that the service relies on, so a
// hand-edited file cannot weaken them.
func (r *Registry) check() error {
	if len(r.Projects) == 0 {
		return fmt.Errorf("no projects")
	}
	owner := map[string]string{}
	for name, p := range r.Projects {
		if !projectName.MatchString(name) {
			return fmt.Errorf("invalid project name %q", name)
		}
		for _, h := range p.Hosts {
			if !hostName.MatchString(strings.TrimPrefix(h, "*.")) {
				return fmt.Errorf("project %s: invalid host %q", name, h)
			}
			if other, ok := owner[h]; ok {
				return fmt.Errorf("host %s claimed by %s and %s", h, other, name)
			}
			owner[h] = name
		}
		for _, d := range p.Convex {
			if !projectName.MatchString(d) {
				return fmt.Errorf("project %s: invalid deployment %q", name, d)
			}
		}
		for _, u := range p.Upstreams {
			if !hostName.MatchString(u) {
				return fmt.Errorf("project %s: invalid upstream %q", name, u)
			}
		}
	}
	return nil
}

// allowsHost reports whether host (a concrete name) is one of the project's
// hosts or a single label under one of its wildcards.
func (p Project) allowsHost(host string) bool {
	for _, h := range p.Hosts {
		if h == host {
			return true
		}
		if suffix, ok := strings.CutPrefix(h, "*"); ok {
			label, found := strings.CutSuffix(host, suffix)
			if found && label != "" && !strings.Contains(label, ".") {
				return true
			}
		}
	}
	return false
}
